"""ENTRY POINT: run python main.py from this folder. See README.md for setup."""

import sys

# Keep generated bytecode out of the clean application folder.
sys.dont_write_bytecode = True

def main(argv=None):
    """Open the GUI, or export an offline demo when a display is unavailable."""
    from src.ui.cli import parse_options, run_demo
    options = parse_options(argv)
    if options.no_gui:
        return run_demo(options)
    try:
        import tkinter as tk
    except ImportError:
        print('Tkinter is unavailable. Running the offline terminal demo instead.')
        return run_demo(options)
    try:
        root = tk.Tk()
    except tk.TclError:
        print('No usable graphical display is available. Running the offline terminal demo instead.')
        return run_demo(options)
    from src.ui.app import GamingJourneyApp
    GamingJourneyApp(root)
    root.mainloop()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
